WITH a AS (SELECT * FROM aggro WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), u AS (SELECT argMin(tuple(kind, distance, facing, dz, vana_hour, weather_id, invisible, sneak, deodorize, clean, mob_level - recorder_level, capture_id, idx, ts_ms), indexOf(['aggro_recorder', 'link', 'aggro_party', 'aggro_other', 'pull_recorder', 'pull_party', 'other'], kind)) AS t FROM a GROUP BY mob_id, intDiv(ts_ms, 10000)), r AS (SELECT t.1 AS kind, t.2 AS distance, t.3 AS facing, t.4 AS dz, t.5 AS hour, t.6 AS weather_id, t.7 AS invisible, t.8 AS sneak, t.9 AS deodorize, t.10 AS clean, t.11 AS gap, t.12 AS capture_id, t.13 AS idx, t.14 AS ts FROM u UNION ALL SELECT * FROM (SELECT 'pass' AS kind, distance, facing, dz, vana_hour AS hour, weather_id, invisible, sneak, deodorize, clean, mob_level - recorder_level AS gap, capture_id, idx, ts_ms AS ts FROM aggro_passes WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged') ORDER BY ts_ms DESC LIMIT 2000)) SELECT r.*, w.name AS weather FROM r LEFT JOIN weather_names w ON w.id = r.weather_id ORDER BY r.ts
